-- =====================================================================
-- V7_13 — Replace 8 skeleton workflow bodies with real flows.
-- All reuse EXISTING pages — no new page_definition rows. Demonstrates
-- page composability: same persona pages drive 10 different variants
-- by being referenced from different workflow bodies.
-- =====================================================================

-- 1. M10.PackUnload — packing-material inbound (3rd-party vendor) ---------
UPDATE workflow_definition SET body_json = '{"code":"M10.PackUnload","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"GATE_PASS_CREATED","assignedRole":"ParkingSecurity"},{"code":"PARKING_IN","assignedRole":"Dispatch"},{"code":"DISPATCH_QUEUED","assignedRole":"QC"},{"code":"QC_APPROVED","assignedRole":"UnloadingSupervisor"},{"code":"QC_REJECTED","terminal":true},{"code":"UNLOADING_DONE","assignedRole":"FrontGate"},{"code":"CLOSED","terminal":true}],"transitions":[{"from":"DRAFT","to":"GATE_PASS_CREATED","trigger":"page.submitted","pageCode":"pico:front-gate-create"},{"from":"GATE_PASS_CREATED","to":"PARKING_IN","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_IN","to":"DISPATCH_QUEUED","trigger":"page.submitted","pageCode":"pico:dispatch-vehicle-entry"},{"from":"DISPATCH_QUEUED","to":"QC_APPROVED","trigger":"page.submitted","pageCode":"pico:qc-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"DISPATCH_QUEUED","to":"QC_REJECTED","trigger":"page.submitted","pageCode":"pico:qc-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_APPROVED","to":"UNLOADING_DONE","trigger":"page.submitted","pageCode":"pico:supervisor-unloading"},{"from":"UNLOADING_DONE","to":"CLOSED","trigger":"page.submitted","pageCode":"pico:gate-pass-closure"}]}' WHERE tenant_id=1 AND code='M10.PackUnload' AND version=1;

-- 2. M10.PackLoading — packing-material outbound ---------------------------
UPDATE workflow_definition SET body_json = '{"code":"M10.PackLoading","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"GATE_PASS_CREATED","assignedRole":"Dispatch"},{"code":"DISPATCH_LOAD_ENTRY","assignedRole":"UnloadingSupervisor"},{"code":"LOADING_IN_PROGRESS","assignedRole":"FrontGate"},{"code":"GATE_PASS_OUT_CLOSED","terminal":true}],"transitions":[{"from":"DRAFT","to":"GATE_PASS_CREATED","trigger":"page.submitted","pageCode":"pico:front-gate-create"},{"from":"GATE_PASS_CREATED","to":"DISPATCH_LOAD_ENTRY","trigger":"page.submitted","pageCode":"pico:dispatch-load-entry"},{"from":"DISPATCH_LOAD_ENTRY","to":"LOADING_IN_PROGRESS","trigger":"page.submitted","pageCode":"pico:loading-in-progress"},{"from":"LOADING_IN_PROGRESS","to":"GATE_PASS_OUT_CLOSED","trigger":"page.submitted","pageCode":"pico:gate-pass-out-closure"}]}' WHERE tenant_id=1 AND code='M10.PackLoading' AND version=1;

