UPDATE workflow_definition SET body_json = '{"code":"M10.IntTransferIn","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"GATE_PASS_CREATED","assignedRole":"ParkingSecurity"},{"code":"PARKING_IN","assignedRole":"Dispatch"},{"code":"DISPATCH_QUEUED","assignedRole":"UnloadingSupervisor"},{"code":"UNLOADING_DONE","assignedRole":"FrontGate"},{"code":"CLOSED","terminal":true}],"transitions":[{"from":"DRAFT","to":"GATE_PASS_CREATED","trigger":"page.submitted","pageCode":"pico:front-gate-create"},{"from":"GATE_PASS_CREATED","to":"PARKING_IN","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_IN","to":"DISPATCH_QUEUED","trigger":"page.submitted","pageCode":"pico:dispatch-vehicle-entry"},{"from":"DISPATCH_QUEUED","to":"UNLOADING_DONE","trigger":"page.submitted","pageCode":"pico:supervisor-unloading"},{"from":"UNLOADING_DONE","to":"CLOSED","trigger":"page.submitted","pageCode":"pico:gate-pass-closure"}]}' WHERE tenant_id=1 AND code='M10.IntTransferIn' AND version=1;

