UPDATE workflow_definition SET body_json = '{"code":"M10.FGLoading","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"GATE_PASS_CREATED","assignedRole":"Dispatch"},{"code":"DISPATCH_LOAD_ENTRY","assignedRole":"UnloadingSupervisor"},{"code":"LOADING_IN_PROGRESS","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_LOADED_OUT","assignedRole":"QC"},{"code":"QC_FINAL_OUT","assignedRole":"FrontGate"},{"code":"GATE_PASS_OUT_CLOSED","terminal":true},{"code":"QC_FINAL_OUT_REJECTED","terminal":true}],"transitions":[{"from":"DRAFT","to":"GATE_PASS_CREATED","trigger":"page.submitted","pageCode":"pico:front-gate-create"},{"from":"GATE_PASS_CREATED","to":"DISPATCH_LOAD_ENTRY","trigger":"page.submitted","pageCode":"pico:dispatch-load-entry"},{"from":"DISPATCH_LOAD_ENTRY","to":"LOADING_IN_PROGRESS","trigger":"page.submitted","pageCode":"pico:loading-in-progress"},{"from":"LOADING_IN_PROGRESS","to":"WEIGHMENT_LOADED_OUT","trigger":"page.submitted","pageCode":"pico:weighment-capture"},{"from":"WEIGHMENT_LOADED_OUT","to":"QC_FINAL_OUT","trigger":"page.submitted","pageCode":"pico:qc-final-out","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHMENT_LOADED_OUT","to":"QC_FINAL_OUT_REJECTED","trigger":"page.submitted","pageCode":"pico:qc-final-out","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_FINAL_OUT","to":"GATE_PASS_OUT_CLOSED","trigger":"page.submitted","pageCode":"pico:gate-pass-out-closure"}]}' WHERE tenant_id=1 AND code='M10.FGLoading' AND version=1;
